<template><el-container style="height:100vh"><el-aside width="220px" style="background:#111827;color:white;padding:20px"><h2>AI 知识操作系统</h2><p>数据中心</p><p>知识加工</p><p>知识裁决</p><p>知识卡片</p><p>知识图谱</p><p>智能查询</p></el-aside><el-main><h2>智能查询</h2><el-card><el-input v-model="q" type="textarea" :rows="4"/><el-button type="primary" style="margin-top:12px" @click="ask">查询</el-button><div v-if="result" style="margin-top:20px"><h3>回答</h3><p>{{result.answer}}</p><h3>策略</h3><el-tag v-for="s in result.strategies" :key="s" style="margin-right:8px">{{s}}</el-tag><h3>引用</h3><el-table :data="result.citations"><el-table-column prop="channel" label="通道"/><el-table-column prop="title" label="标题"/></el-table></div></el-card></el-main></el-container></template>
<script setup>import{ref}from'vue';import axios from'axios';const q=ref('知识为什么需要裁决？');const result=ref(null);async function ask(){const r=await axios.post('/api/knowledge/query',{knowledgeBaseId:1,query:q.value,topK:10,userId:'demo'});result.value=r.data.data}</script>
